namespace Ordering;

/// <summary>Coordinates product return, refund, and restocking operations.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnProcessor _returnProcessor;
    private readonly RefundService _refundService;
    private readonly RestockService _restockService;

    public ReturnsHandler()
    {
        var returnRegistry = new ReturnRegistry();
        _restockService = new RestockService();
        _returnProcessor = new ReturnProcessor(returnRegistry, _restockService);
        _refundService = new RefundService();
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _returnProcessor.ProcessReturn(order, customer);

    public bool IsReturnable(Order order) =>
        _returnProcessor.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refundService.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _refundService.LogRefund(order, amount);

    public int Restock(Order order) =>
        _restockService.Restock(order);
}

internal sealed class ReturnRegistry
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);

    public bool Contains(string reference) => _processedReferences.Contains(reference);

    public void Add(string reference) => _processedReferences.Add(reference);
}

internal sealed class ReturnProcessor
{
    private readonly ReturnRegistry _returnRegistry;
    private readonly RestockService _restockService;

    public ReturnProcessor(ReturnRegistry returnRegistry, RestockService restockService)
    {
        _returnRegistry = returnRegistry;
        _restockService = restockService;
    }

    public string ProcessReturn(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_returnRegistry.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _restockService.Schedule(line.Sku, line.Quantity);
        }

        if (!_restockService.HasScheduledStock)
            return "no returnable lines";

        _returnRegistry.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_returnRegistry.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                return true;
        }

        return false;
    }
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal ComputeRefund(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;
        return refund < 0m ? 0m : refund;
    }

    public void LogRefund(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;

        if (_refundLog.Count == 0 || amount > 100m)
            _refundLog.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _refundLog.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _refundLog.Add($"{order.Reference}:mid:{amount}");
        else
            _refundLog.Add($"{order.Reference}:small:{amount}");

        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }
}

internal sealed class RestockService
{
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public bool HasScheduledStock => _restockBySku.Count != 0;

    public void Schedule(string sku, int quantity)
    {
        _restockBySku[sku] = _restockBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;

            if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _restockBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                _restockBySku[sku] = line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }
}
